mapper.select:
select tab.* from( select ( CASE WHEN =0 THEN '未融资' WHEN cfp.apply_amount - >0 THEN '部分融资' ELSE '完全融资' END) AS planStatus, cfp.*, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'CHS.CURRENCY_TYPE' and cfp.currency = sc.code_value) currency_n, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'FIN.FINANCE_METHOD' and cfp.finance_method = sc.code_value) finance_method_n, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'CAP.CAP_CONFIRM_STATUS' and cfp.confirm_status = sc.code_value) confirm_status_n, ( cfp.apply_amount - )rest_amount, ( select su.description from sys_user su where su.user_id = cfp.user_id )user_name, ( select company_short_name from fnd_company fc where fc.company_id = cfp.company_id )company_name from cap_financing_plan cfp )tab where 1 = 1
and tab.company_id = #{request.companyId}
and tab.company_id = #{companyId}
and tab.plan_id = #{planId}
and (tab.plan_name like '%'||#{planInfo}||'%' or tab.plan_number like '%'||#{planInfo}||'%')
and tab.plan_name like '%'||#{planInfo}||'%'
and tab.plan_number like '%'||#{planInfo}||'%'
and tab.period = #{period}
and tab.confirm_status = #{confirmStatus}
and tab.period in
#{item}
and tab.apply_amount = #{applyAmount}
and tab.rest_amount = 0
and tab.rest_amount > 0
AND tab.creation_date >= #{creationDateStart}
AND tab.creation_date <= #{creationDateEnd}
AND planStatus=#{planStatus}
order by tab.creation_date desc
